/**
 * CasesBranch
 *
 * Case `when` leads to `branches[then]`.
 */
export type CasesBranch = {
    /**
     * When
     */
    when: RangeCondition | StringMatchCondition | IsInCondition;
    /**
     * Then
     */
    then: number;
};

/**
 * CasesIsIn
 *
 * Branch `i` is taken for the first value set `conditions[i]` holding `x`; branch `len(conditions)` otherwise.
 */
export type CasesIsIn = {
    /**
     * Type
     */
    type?: 'cases';
    /**
     * Op
     */
    op?: 'isin';
    /**
     * Id
     */
    id?: string | null;
    feature: Feature;
    /**
     * Conditions
     */
    conditions: Array<IsInCondition>;
};

/**
 * CasesIsInRule
 */
export type CasesIsInRule = {
    /**
     * Conditions
     */
    conditions: Array<CasesBranch>;
    /**
     * Otherwise
     */
    otherwise: number;
    /**
     * Branches
     */
    branches: Array<LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule>;
    /**
     * Type
     */
    type?: 'cases';
    /**
     * Op
     */
    op?: 'isin';
    /**
     * Id
     */
    id?: string | null;
    feature: Feature;
};

/**
 * CasesRanges
 *
 * Branch `i` is taken for the first band `conditions[i]` that holds; branch `len(conditions)` otherwise.
 *
 * With `strict` (the default), literal bands must be sorted and contiguous:
 * `CasesRanges(feature="score", conditions=[{"max": 30.0}, {"min": 30.0}])`.
 */
export type CasesRanges = {
    /**
     * Type
     */
    type?: 'cases';
    /**
     * Op
     */
    op?: 'ranges';
    /**
     * Id
     */
    id?: string | null;
    feature: Feature;
    end_logic?: RangeEndLogic;
    /**
     * Strict
     */
    strict?: boolean;
    /**
     * Conditions
     */
    conditions: Array<RangeCondition>;
};

/**
 * CasesRangesRule
 *
 * A `CasesRanges` whose cases point into a nested `branches` list, with `otherwise` indexing it too.
 */
export type CasesRangesRule = {
    /**
     * Conditions
     */
    conditions: Array<CasesBranch>;
    /**
     * Otherwise
     */
    otherwise: number;
    /**
     * Branches
     */
    branches: Array<LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule>;
    /**
     * Type
     */
    type?: 'cases';
    /**
     * Op
     */
    op?: 'ranges';
    /**
     * Id
     */
    id?: string | null;
    feature: Feature;
    end_logic?: RangeEndLogic;
    /**
     * Strict
     */
    strict?: boolean;
};

/**
 * CasesStringMatch
 *
 * Branch `i` is taken for the first `conditions[i]` whose patterns match; branch `len(conditions)` otherwise.
 */
export type CasesStringMatch = {
    /**
     * Type
     */
    type?: 'cases';
    /**
     * Op
     */
    op?: 'string_match';
    /**
     * Id
     */
    id?: string | null;
    feature: Feature;
    match_type?: StringMatchType;
    /**
     * Case Sensitive
     */
    case_sensitive?: boolean;
    /**
     * Trim Whitespace
     */
    trim_whitespace?: boolean;
    /**
     * Conditions
     */
    conditions: Array<StringMatchCondition>;
};

/**
 * CasesStringMatchRule
 */
export type CasesStringMatchRule = {
    /**
     * Conditions
     */
    conditions: Array<CasesBranch>;
    /**
     * Otherwise
     */
    otherwise: number;
    /**
     * Branches
     */
    branches: Array<LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule>;
    /**
     * Type
     */
    type?: 'cases';
    /**
     * Op
     */
    op?: 'string_match';
    /**
     * Id
     */
    id?: string | null;
    feature: Feature;
    match_type?: StringMatchType;
    /**
     * Case Sensitive
     */
    case_sensitive?: boolean;
    /**
     * Trim Whitespace
     */
    trim_whitespace?: boolean;
};

/**
 * CompositeCondition
 *
 * AND/OR/NOT over nested conditions. As a tree node, branch 0 is taken when it holds, branch 1 otherwise.
 */
export type CompositeCondition = {
    /**
     * Type
     */
    type?: 'composite';
    /**
     * Id
     */
    id?: string | null;
    op: LogicOp;
    /**
     * Conditions
     */
    conditions: Array<UnaryLessThanEqual | UnaryLessThan | UnaryEqual | UnaryGreaterThan | UnaryGreaterThanEqual | UnaryNotEqual | UnaryBetween | UnaryIsIn | UnaryStringMatch | UnaryIsTrue | UnaryIsFalse | CompositeCondition>;
};

/**
 * CompositeRule
 *
 * A `CompositeNode` with its `then` and `otherwise` rules nested.
 */
export type CompositeRule = {
    /**
     * Then
     */
    then?: LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule | null;
    /**
     * Otherwise
     */
    otherwise?: LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule | null;
    /**
     * Type
     */
    type?: 'composite';
    /**
     * Id
     */
    id?: string | null;
    op: LogicOp;
    /**
     * Conditions
     */
    conditions: Array<UnaryLessThanEqual | UnaryLessThan | UnaryEqual | UnaryGreaterThan | UnaryGreaterThanEqual | UnaryNotEqual | UnaryBetween | UnaryIsIn | UnaryStringMatch | UnaryIsTrue | UnaryIsFalse | CompositeCondition>;
};

/**
 * ComputedFeature
 *
 * A feature computed from other columns, e.g. `{"type": "computed", "expression": "x - y"}`.
 */
export type ComputedFeature = {
    /**
     * Type
     */
    type?: 'computed';
    /**
     * Expression
     */
    expression: string;
};

/**
 * Feature
 *
 * A column name, or a `ComputedFeature`.
 */
export type Feature = ComputedFeature | string;

/**
 * FlatRuleDocument
 *
 * One nested rule.
 *
 * Nodes without an `id` get one from their path: the root is `"0"`, its
 * `then` branch `"0.0"`, a cases node's `branches[2]` `"<id>.2"`.
 *
 * Example (the `V3TreeDocument` example's logic, with path ids)::
 *
 * FlatRuleDocument(
 * rule={"rule": {"type": "unary", "condition": {"op": "<", "feature": "age", "threshold": 30},
 * "then": {"type": "leaf", "result_idx": 0}}},
 * output={"data": [{"group": "young"}], "default": {"group": "adult"}, "dtypes": [("group", "String")]},
 * ).to_tree()
 */
export type FlatRuleDocument = {
    /**
     * Name
     */
    name?: string;
    output: TreeOutput;
    /**
     * Parameters
     */
    parameters?: {
        [key: string]: ParameterInfo;
    };
    input_schema?: TStruct | null;
    /**
     * Type
     */
    type?: 'flat_rule';
    rule: RuleRoot;
};

/**
 * IsInCondition
 */
export type IsInCondition = {
    /**
     * Values
     */
    values: Array<number | number | ParamRef> | ParamRef;
};

/**
 * LeafNode
 *
 * Selects row `result_idx` of the tree's output table; -1 selects the default row.
 */
export type LeafNode = {
    /**
     * Type
     */
    type?: 'leaf';
    /**
     * Id
     */
    id?: string | null;
    /**
     * Result Idx
     */
    result_idx?: number;
};

/**
 * LogicOp
 */
export type LogicOp = 'and' | 'or' | 'not';

/**
 * MultiEdgeData
 *
 * The branch indices of the source node this edge leaves from.
 */
export type MultiEdgeData = {
    /**
     * Sourceindex
     */
    sourceIndex: Array<number>;
};

/**
 * MultiSourceEdge
 */
export type MultiSourceEdge = {
    /**
     * Id
     */
    id?: string | null;
    /**
     * Source
     */
    source: string;
    /**
     * Target
     */
    target: string;
    data: MultiEdgeData;
};

/**
 * NullHandling
 *
 * What a string match does with a null string.
 *
 * `no_match` (the default): the match is false. `match`: the match is true.
 * `error`: a null in the column is a `MissingInputError`.
 */
export type NullHandling = 'match' | 'no_match' | 'error';

/**
 * ParamRef
 *
 * A config value read from the params document instead of written inline.
 *
 * `{"param": "hi_thresh", "default": 0.7}` is a local param of the step;
 * `{"param": "base_rate", "shared": true}` reads `shared.base_rate`.
 *
 * Example::
 *
 * ThresholdRule(name="hi", column="score", threshold=ParamRef(param="hi_thresh", default=0.7))
 * # params document: {"hi": {"hi_thresh": 0.8}}
 */
export type ParamRef = {
    /**
     * Param
     */
    param: string;
    /**
     * Default
     */
    default?: unknown;
    /**
     * Shared
     */
    shared?: boolean;
};

/**
 * ParameterInfo
 *
 * A param declared in an older document's `parameters` block; its default fills matching refs.
 */
export type ParameterInfo = {
    /**
     * Type
     */
    type?: unknown;
    /**
     * Default Value
     */
    default_value?: unknown;
};

/**
 * Position
 */
export type Position = {
    /**
     * X
     */
    x?: number;
    /**
     * Y
     */
    y?: number;
};

/**
 * PositionedNode
 */
export type PositionedNode = {
    /**
     * Id
     */
    id: string;
    position?: Position;
    /**
     * Data
     */
    data: LeafNode | UnaryNode | CasesRanges | CasesStringMatch | CasesIsIn | CompositeCondition;
};

/**
 * PrioritizationMode
 */
export type PrioritizationMode = 'first_match' | 'all';

/**
 * PrioritizedFlatRuleDocument
 *
 * Several nested rules in priority order; see `Tree` for `mode`. Root ids default to `"0"`, `"1"`, ...
 */
export type PrioritizedFlatRuleDocument = {
    /**
     * Name
     */
    name?: string;
    output: TreeOutput;
    /**
     * Parameters
     */
    parameters?: {
        [key: string]: ParameterInfo;
    };
    input_schema?: TStruct | null;
    /**
     * Type
     */
    type?: 'prioritized_flat_rule';
    /**
     * Rules
     */
    rules: Array<RuleRoot>;
    mode?: PrioritizationMode;
};

/**
 * RangeCondition
 *
 * One band of a `CasesRanges`; which end is closed is the node's `end_logic`.
 */
export type RangeCondition = {
    /**
     * Min
     */
    min?: number | number | ParamRef | null;
    /**
     * Max
     */
    max?: number | number | ParamRef | null;
};

/**
 * RangeEndLogic
 *
 * Which end of a range band is closed: `[lo, hi)` or `(lo, hi]`.
 */
export type RangeEndLogic = 'lower_inclusive' | 'upper_inclusive';

/**
 * RuleMeta
 */
export type RuleMeta = {
    /**
     * Name
     */
    name?: string | null;
    /**
     * Description
     */
    description?: string | null;
};

/**
 * RuleRoot
 */
export type RuleRoot = {
    meta?: RuleMeta;
    /**
     * Rule
     */
    rule: LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule;
};

/**
 * StringMatchCondition
 */
export type StringMatchCondition = {
    /**
     * Patterns
     */
    patterns: Array<string | ParamRef>;
};

/**
 * StringMatchType
 */
export type StringMatchType = 'exact' | 'starts_with' | 'contains' | 'ends_with' | 'regex';

/**
 * SubTree
 */
export type SubTree = {
    /**
     * Id
     */
    id?: string | null;
    /**
     * Name
     */
    name?: string | null;
};

/**
 * TreeMetadata
 */
export type TreeMetadata = {
    /**
     * Name
     */
    name?: string | null;
    /**
     * Description
     */
    description?: string | null;
};

/**
 * TreeOutput
 *
 * The rows a tree's leaves select: `data[result_idx]`, or `default` for -1.
 *
 * `dtypes` names each output column and its type, e.g. `[("band", "String")]`.
 * A column a row leaves out is null there; no `default` (or `{}`) is a row of nulls.
 * `{"type": "Custom", "type_id": "bands"}` names a categorical in `type_defs`, a string column.
 *
 * Example::
 *
 * TreeOutput(data=[{"band": "low"}], default={"band": "high"}, dtypes=[("band", "String")])
 */
export type TreeOutput = {
    /**
     * Data
     */
    data?: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Default
     */
    default?: {
        [key: string]: unknown;
    } | null;
    dtypes?: TStruct;
    /**
     * Type Defs
     */
    type_defs?: {
        [key: string]: unknown;
    };
};

/**
 * UnaryBetween
 *
 * `min <= x <= max`, closed at both ends; either bound may be left out.
 */
export type UnaryBetween = {
    /**
     * Min
     */
    min?: number | number | ParamRef | null;
    /**
     * Max
     */
    max?: number | number | ParamRef | null;
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Op
     */
    op?: 'between';
};

/**
 * UnaryEqual
 */
export type UnaryEqual = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Threshold
     */
    threshold: number | number | ParamRef;
    /**
     * Op
     */
    op?: '==';
};

/**
 * UnaryGreaterThan
 */
export type UnaryGreaterThan = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Threshold
     */
    threshold: number | number | ParamRef;
    /**
     * Op
     */
    op?: '>';
};

/**
 * UnaryGreaterThanEqual
 */
export type UnaryGreaterThanEqual = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Threshold
     */
    threshold: number | number | ParamRef;
    /**
     * Op
     */
    op?: '>=';
};

/**
 * UnaryIsFalse
 */
export type UnaryIsFalse = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Op
     */
    op?: 'is_false';
};

/**
 * UnaryIsIn
 *
 * `x` equals one of `values`; a single `ParamRef` means equality with that param.
 */
export type UnaryIsIn = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Op
     */
    op?: 'isin';
    /**
     * Values
     */
    values: Array<number | number | ParamRef> | ParamRef;
};

/**
 * UnaryIsTrue
 */
export type UnaryIsTrue = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Op
     */
    op?: 'is_true';
};

/**
 * UnaryLessThan
 */
export type UnaryLessThan = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Threshold
     */
    threshold: number | number | ParamRef;
    /**
     * Op
     */
    op?: '<';
};

/**
 * UnaryLessThanEqual
 */
export type UnaryLessThanEqual = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Threshold
     */
    threshold: number | number | ParamRef;
    /**
     * Op
     */
    op?: '<=';
};

/**
 * UnaryNode
 *
 * One condition. Branch 0 is taken when it holds, branch 1 otherwise.
 */
export type UnaryNode = {
    /**
     * Type
     */
    type?: 'unary';
    /**
     * Id
     */
    id?: string | null;
    /**
     * Condition
     */
    condition: ({
        op: '<=';
    } & UnaryLessThanEqual) | ({
        op: '<';
    } & UnaryLessThan) | ({
        op: '==';
    } & UnaryEqual) | ({
        op: '>';
    } & UnaryGreaterThan) | ({
        op: '>=';
    } & UnaryGreaterThanEqual) | ({
        op: '!=';
    } & UnaryNotEqual) | ({
        op: 'between';
    } & UnaryBetween) | ({
        op: 'isin';
    } & UnaryIsIn) | ({
        op: 'string_match';
    } & UnaryStringMatch) | ({
        op: 'is_true';
    } & UnaryIsTrue) | ({
        op: 'is_false';
    } & UnaryIsFalse);
};

/**
 * UnaryNotEqual
 */
export type UnaryNotEqual = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Threshold
     */
    threshold: number | number | ParamRef;
    /**
     * Op
     */
    op?: '!=';
};

/**
 * UnaryRule
 *
 * A `UnaryNode` with its `then` and `otherwise` rules nested; a missing one selects the default row.
 */
export type UnaryRule = {
    /**
     * Then
     */
    then?: LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule | null;
    /**
     * Otherwise
     */
    otherwise?: LeafNode | UnaryRule | CasesRangesRule | CasesStringMatchRule | CasesIsInRule | CompositeRule | null;
    /**
     * Type
     */
    type?: 'unary';
    /**
     * Id
     */
    id?: string | null;
    /**
     * Condition
     */
    condition: ({
        op: '<=';
    } & UnaryLessThanEqual) | ({
        op: '<';
    } & UnaryLessThan) | ({
        op: '==';
    } & UnaryEqual) | ({
        op: '>';
    } & UnaryGreaterThan) | ({
        op: '>=';
    } & UnaryGreaterThanEqual) | ({
        op: '!=';
    } & UnaryNotEqual) | ({
        op: 'between';
    } & UnaryBetween) | ({
        op: 'isin';
    } & UnaryIsIn) | ({
        op: 'string_match';
    } & UnaryStringMatch) | ({
        op: 'is_true';
    } & UnaryIsTrue) | ({
        op: 'is_false';
    } & UnaryIsFalse);
};

/**
 * UnaryStringMatch
 *
 * `x` matches any of `patterns`.
 */
export type UnaryStringMatch = {
    /**
     * Type
     */
    type?: 'unary';
    feature: Feature;
    /**
     * Op
     */
    op?: 'string_match';
    /**
     * Patterns
     */
    patterns: Array<string | ParamRef>;
    match_type?: StringMatchType;
    /**
     * Case Sensitive
     */
    case_sensitive?: boolean;
    /**
     * Trim Whitespace
     */
    trim_whitespace?: boolean;
    null_handling?: NullHandling;
};

/**
 * V3TreeDocument
 *
 * A v3 tree: `nodes` say what each node tests, `edges` wire branch `sourceIndex` of `source` to `target`.
 *
 * A branch with no edge selects the default output row. The root is the
 * node nothing points at (the first listed subtree's, when there are several).
 *
 * Example (age < 30 is "young", anything else the default "adult")::
 *
 * V3TreeDocument(
 * nodes=[{"id": "root", "data": {"type": "unary", "condition": {"op": "<", "feature": "age", "threshold": 30}}},
 * {"id": "young", "data": {"type": "leaf", "result_idx": 0}}],
 * edges=[{"source": "root", "target": "young", "data": {"sourceIndex": 0}}],
 * output={"data": [{"group": "young"}], "default": {"group": "adult"}, "dtypes": [("group", "String")]},
 * ).to_tree()
 */
export type V3TreeDocument = {
    /**
     * Name
     */
    name?: string;
    output?: TreeOutput;
    /**
     * Parameters
     */
    parameters?: {
        [key: string]: ParameterInfo;
    };
    input_schema?: TStruct | null;
    /**
     * Type
     */
    type?: 'v3-tree' | 'ui-tree';
    metadata?: TreeMetadata | null;
    /**
     * Nodes
     */
    nodes: Array<PositionedNode>;
    /**
     * Edges
     */
    edges?: Array<MultiSourceEdge>;
    /**
     * Subtrees
     */
    subtrees?: Array<SubTree>;
    /**
     * Formatversion
     */
    formatVersion?: 3;
};

export type TreeDocument = V3TreeDocument | FlatRuleDocument | PrioritizedFlatRuleDocument;

